// Конфиг из Data Table integration_config (key/value)
const cfg = Object.fromEntries($('Config').all().map(i => [i.json.key, i.json.value]));
const e = $('Error Trigger').first().json;

// Маскируем секреты: путь входящего вебхука Битрикса и токены ботов Telegram
const mask = (s) => String(s ?? '')
  .replace(/\/rest\/\d+\/[A-Za-z0-9]+/g, '/rest/***')
  .replace(/\d{6,}:[A-Za-z0-9_-]{30,}/g, '***');
// Экранируем под parse_mode=HTML, иначе _ и * в тексте ошибки ломают отправку
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const exec = e.execution || {};
const err = exec.error || e.trigger?.error || {};
const text = [
  '🚨 <b>Ошибка в n8n</b>',
  `Workflow: ${esc(e.workflow?.name ?? '—')} (id ${esc(e.workflow?.id ?? '—')})`,
  `Нода: ${esc(exec.lastNodeExecuted ?? err.node?.name ?? '—')}`,
  `Ошибка: ${esc(mask(err.message || 'unknown').slice(0, 1000))}`,
  err.description ? `Детали: ${esc(mask(err.description).slice(0, 1000))}` : null,
  `Execution: ${esc(exec.url ?? (exec.id ? 'id ' + exec.id : '—'))}`,
].filter(Boolean).join('\n');

return [{ json: { chatId: cfg.manager_chat_id, text } }];
